// Auto-generated statics (base64-encoded)
// Auto-generated by build-origin-worker.js
const STATICS = {
  html: '',
  js: '',
  wasm: '',
};


// Decode base64 to Uint8Array
function base64ToUint8Array(b64) {
  const binaryStr = atob(b64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) {
    bytes[i] = binaryStr.charCodeAt(i);
  }
  return bytes;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const pathname = url.pathname;

    // Serve static assets
    if (pathname === '/' || pathname === '/consent') {
      const body = base64ToUint8Array(STATICS.html);
      return new Response(body, {
        status: 200,
        headers: {
          'content-type': 'text/html; charset=utf-8',
          'content-length': body.length,
          'cache-control': 'public, max-age=300',
        },
      });
    }

    if (pathname === '/pkg/tcf_decoder.js') {
      const body = base64ToUint8Array(STATICS.js);
      return new Response(body, {
        status: 200,
        headers: {
          'content-type': 'application/javascript',
          'content-length': body.length,
          'cache-control': 'public, max-age=300',
        },
      });
    }

    if (pathname === '/pkg/tcf_decoder_bg.wasm') {
      const body = base64ToUint8Array(STATICS.wasm);
      return new Response(body, {
        status: 200,
        headers: {
          'content-type': 'application/wasm',
          'content-length': body.length,
          'cache-control': 'public, max-age=300',
        },
      });
    }

    // Echo endpoint: return request path + headers as JSON
    const respBody = JSON.stringify({
      origin: true,
      method: request.method,
      path: url.pathname + url.search,
      headers: Object.fromEntries(request.headers),
      timestamp_ms: Date.now(),
    });

    return new Response(respBody, {
      status: 200,
      headers: {
        'content-type': 'application/json',
        'content-length': new TextEncoder().encode(respBody).length,
      },
    });
  },
};
